// Define the tagged type for DateTime64
#[verus]
pub enum DateTime64 {
    Nat,
    Valid(u64),
}

// Function to determine if each element in the input vector is of the Nat case
#[verus]
pub fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    // Precondition: The input vector must have a non-negative length
    assert(x.len() >= 0);

    // Initialize the output vector with the same length as the input
    let mut result: Vec<bool> = vec![false; x.len()];

    // Loop through each element in the input vector
    for i in 0..x.len() {
        // Invariant: The result vector must have the same length as the input vector
        assert(result.len() == x.len());

        // Check the case of the current element
        match x[i] {
            DateTime64::Nat => {
                // If the element is Nat, set the corresponding result to true
                result[i] = true;
            }
            DateTime64::Valid(_) => {
                // If the element is Valid, set the corresponding result to false
                result[i] = false;
            }
        }
    }

    // Postcondition: The output vector must have the same length as the input
    assert(result.len() == x.len());

    // Ensure that the output is correct
    for i in 0..x.len() {
        assert(result[i] == (matches!(x[i], DateTime64::Nat)));
    }

    // Return the result vector
    result
}